using UnityEngine;

public class SpawnMaster : MonoBehaviour
{
    public GameObject prefab;

    void Start()
    {
        Spawn();
        Spawn(new Vector3(3, 0, 0));
        Spawn(new Vector3(0, 0, 5), Quaternion.Euler(0, 45, 0));
        Spawn(3);
    }

    void Spawn()
    {
        Spawn(Vector3.zero, Quaternion.identity);
    }

    void Spawn(Vector3 position)
    {
        Spawn(position, Quaternion.identity);
    }

    void Spawn(Vector3 position, Quaternion rotation)
    {
        Instantiate(prefab, position, rotation);
    }

    void Spawn(int count)
    {
        for (int i = 0; i < count; i++)
        {
            Spawn(new Vector3(i * 2f, 0, 0));
        }
    }
}
